import sys

def solve() -> None:
    input = sys.stdin.readline
    Q = int(input())
    out_lines = []
    for _ in range(Q):
        L, X, P = map(int, input().split())
        cur = X
        i = L
        while i >= P:
            if cur == 0:
                break
            if cur < i:
                # cur 保持不变直到 i = cur
                if P > cur:
                    break      # 答案就是 cur
                else:
                    cur = 0    # P <= cur，会经过 cur % cur = 0
                    break
            else:
                cur %= i
                i -= 1
        out_lines.append(str(cur))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
